sys_script_include.script:
var PDIObserverAjax = Class.create();
PDIObserverAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    registerNewPDI: function() {
        // 1. Retrieve parameters sent from the client script
        var url = this.getParameter('sysparm_url');
        var pEmail = this.getParameter('sysparm_p_email');
        var pPass = this.getParameter('sysparm_p_pass');
        var iUser = this.getParameter('sysparm_i_user');
        var iPass = this.getParameter('sysparm_i_pass');

        // 2. Validate mandatory field on the server side
        if (!url) {
            return "ERROR: Instance URL is missing";
        }

        try {
            // 3. Initialize GlideRecord for the PDI instance table
            // NOTE: Replace 'x_abc_' with your actual application scope/vendor code
            var grPDI = new GlideRecord('x_1836491_pdiobs_0_observer_instance');
            grPDI.initialize();

            // 4. Map the received values to the table fields
            grPDI.instance_url = url;
            grPDI.portal_email = pEmail;
            grPDI.instance_username = iUser;

            // Assign passwords directly. ServiceNow automatically encrypts 
            // them into the "Password (2 Way Encrypted)" field type.
            if (pPass) grPDI.portal_password = pPass;
            if (iPass) grPDI.instance_password = iPass;

            // 5. Add an initial log entry for the Developer Portal action
            var currentTime = new GlideDateTime().getDisplayValue();
            grPDI.portal_action_log = "PDI configuration created at " + currentTime;

            // 6. Insert the record into the database
            var newSysId = grPDI.insert();

            if (newSysId) {
                return "SUCCESS_" + newSysId;
            } else {
                return "ERROR: Database insert failed";
            }

        } catch (ex) {
            // 7. Handle and log any potential server-side errors
            gs.error("PDIObserverAjax Error: " + ex.getMessage());
            return "ERROR: " + ex.getMessage();
        }
    },
    type: 'PDIObserverAjax'
});
